// ============================================
// VALIDATION INPUT - Entity Comment
// ============================================

const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];
const startTime = Date.now();

// --- Get tenant_id from header or body ---
const tenantId = headers['x-tenant-id'] || headers['X-Tenant-ID'] || body.tenant_id || ctx.tenant_id || null;

// --- Backend API configuration ---
const backendApiUrl = body.backend_api_url || ctx.backend_api_url || null;
const backendServiceToken = body.backend_service_token || ctx.backend_service_token || null;

// --- Required fields ---
const action = (body.action || ctx.action || '').toLowerCase();
const validActions = ['comment', 'list', 'edit', 'delete'];
if (!action || !validActions.includes(action)) {
  errors.push(`action invalide: '${action}' (doit etre: ${validActions.join(', ')})`);
}

const entityId = body.entity_id || ctx.entity_id || '';
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!entityId) {
  errors.push('entity_id requis');
} else if (!uuidRegex.test(entityId)) {
  errors.push('entity_id invalide (format UUID requis)');
}

const userId = body.user_id || ctx.user_id || '';
if (!userId || userId.trim().length === 0) {
  errors.push('user_id requis');
}

// --- Optional fields ---
const entityType = body.entity_type || ctx.entity_type || '';
const validEntityTypes = ['recipe', 'document', 'course', 'quiz', 'flashcard'];
if (entityType && !validEntityTypes.includes(entityType)) {
  errors.push(`entity_type invalide: '${entityType}' (doit etre: ${validEntityTypes.join(', ')})`);
}
const guildId = body.guild_id || ctx.guild_id || null;
const content = body.content || ctx.content || '';
const commentId = body.comment_id || ctx.comment_id || '';
const parentId = body.parent_id || ctx.parent_id || null;
const limit = parseInt(body.limit || ctx.limit || 20);
const offset = parseInt(body.offset || ctx.offset || 0);

// --- Conditional validations based on action ---
if ((action === 'comment' || action === 'edit') && (!content || content.trim().length === 0)) {
  errors.push('content requis pour action=' + action);
}

if ((action === 'edit' || action === 'delete') && !commentId) {
  errors.push('comment_id requis pour action=' + action);
} else if ((action === 'edit' || action === 'delete') && commentId && !uuidRegex.test(commentId)) {
  errors.push('comment_id invalide (format UUID requis)');
}

if (parentId && !uuidRegex.test(parentId)) {
  errors.push('parent_id invalide (format UUID requis)');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId || null,
    guild_id: guildId,
    startTime: startTime
  };
}

return {
  valid: true,
  action: action,
  entity_id: entityId,
  entity_type: entityType,
  user_id: userId.trim(),
  guild_id: guildId,
  content: content.trim(),
  comment_id: commentId || null,
  parent_id: parentId,
  tenant_id: tenantId,
  backend_api_url: backendApiUrl,
  backend_service_token: backendServiceToken,
  limit: limit,
  offset: offset,
  startTime: startTime
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;
const startTime = input.startTime || Date.now();

return {
  success: false,
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'postgresql',
    mode: 'error',
    latency_ms: Date.now() - startTime,
    user_id: input.user_id,
    guild_id: input.guild_id
  }
};

// ============================================
// FORMAT CREATE COMMENT RESPONSE
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();
const latency = Date.now() - startTime;

// Handle API errors
const statusCode = input.statusCode || 200;
const body = input.body || input;

if (statusCode >= 400 || body.error || body.detail) {
  return {
    success: false,
    error: {
      code: 'API_ERROR',
      message: body.error?.message || body.detail || 'Failed to create comment',
      http_status: statusCode >= 400 ? statusCode : 500
    },
    user_id: prevData.user_id,
    guild_id: prevData.guild_id,
    _trace: {
      service_response: body,
      provider: 'postgresql',
      action: 'comment',
      latency_ms: latency,
      user_id: prevData.user_id,
      guild_id: prevData.guild_id
    }
  };
}

// Success response
return {
  success: true,
  data: {
    comment_id: body.comment_id || body.id,
    entity_id: prevData.entity_id,
    content: prevData.content,
    user_id: prevData.user_id,
    created_at: body.created_at || new Date().toISOString()
  },
  user_id: prevData.user_id,
  guild_id: prevData.guild_id,
